"""June planning after reading all eleven poems; preserves historical issue identity."""
import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-20';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(415, 'water-waiting-for-birds', 'Water waiting for birds', 'During extreme heat the mother leaves water on the balcony, but the birds do not return. The still waiting bowl carries concern for an absent life and a distant loved one without illustrating a disaster or making the absence decorative.', 'Original horizontal 3:2 restrained terracotta and pale-grey gouache study. One shallow unglazed earthen bowl containing a modest amount of water rests on an ordinary balcony floor at lower left. Seen obliquely from above, coherent rim ellipse and horizontal water surface below the rim, small dull sky reflection rather than a mirror. A hard warm patch of afternoon sun stops short of the bowl; it sits in partial shade under an unseen parapet. Fine matte clay and plain concrete, just one slight drying water mark near its base. Most of frame is empty pale floor, no birds, feathers, dead animals, flowers, people, rail decorations, city panorama or writing. Convey care continuing through oppressive heat and waiting; not a luxury bowl product advertisement.'), (417, 'road-into-wet-air', 'Road into wet air', 'The poem experiences the hills through fog, dampness and a winding road. A restrained imagined hill-road study accompanies that feeling without pretending to document an identified Jatinga viewpoint.', 'Original horizontal 3:2 atmospheric watercolor and a little soft charcoal. A narrow ordinary hill road enters from the cropped lower left, bends once behind a dark green shoulder of forest and disappears into low wet cloud. Only two overlapping slopes visible, unequal and partly obscured; a few near leaves and a damp roadside edge carry detail, distant trees merge into pale grey-green wash. The road surface is dull from moisture, no bright mirror puddle or perfect decorative S curve. Fog obscures portions according to depth, no glowing sunbeams, neon blue peaks, fantasy mountains or birds. No cars, buildings, road signs, people or exact landmark claims. A poetic imagined response to cool wet hill air, calm and spatially believable, with pale cloud space toward upper right.'), (420, 'after-the-gush-of-rain', 'After the gush of rain', 'The short sequence turns public London encounters into rain-interrupted moments. A wet park seat after people have hurried away leaves that interruption open without staging tourists or claiming to depict a particular visit.', 'Original horizontal 3:2 loose ink drawing with muted grey and spring-green watercolor. Close cropped end of an ordinary public park bench after a sudden shower, two or three continuous horizontal wooden seat slats viewed at a believable shallow angle, simple dark iron support partly visible beneath. Small uneven beads and damp patches remain on the wood; behind it a quiet wash of wet path and a few green grass strokes, no scenic park panorama. No umbrella, person, bag or object arranged on the seat: absence after the hurried dispersal is the subject. Seat mostly left half, empty washed air/path toward right. Ink resolves a few joins then loosens at the crop; light soft after rain, no glossy varnish, postcard landmarks, readable plaques or text.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-20/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue20. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. No people, portraits or documentary location claims. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt)
 items.append(dict(id=ident,edition=20,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-20/{ident}/v1.png',attempts=[],independent=False))
plain=[{'poem_id': 416, 'rationale': 'The mother’s absence unfolds through a precise sequence of household routines. Let that accumulation work without selecting a sentimental prop as a substitute for her life.', 'status': 'pending'}, {'poem_id': 423, 'rationale': 'The poem addresses insomnia, pills and the longing for maternal rescue. Keep it text-led; do not invent a body, medication display or literal self-harm scene.', 'status': 'pending'}, {'poem_id': 424, 'rationale': 'The poem challenges victim blaming directly. Preserve that argument without illustrating sexual violence or inventing a victim.', 'status': 'pending'}]
for p in (S/'content/editions/issue-20').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
b=dict(edition=20,status='planned',created_at=now,poems_read=sorted(json.loads(p.read_text())['id'] for p in (S/'content/editions/issue-20').glob('poem-*.json')),direction='June holds several kinds of weather: water left for absent birds in heat, a hill road dissolved in wet air, and a park seat after a sudden shower. Clay gouache, broad landscape washes and spare ink vary scale and atmosphere. Personal bereavement, insomnia and the challenge to victim blaming remain text-led.',items=items,text_led=plain,independent=False)
(B/'batch.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n');ed=next(x for x in q['editions'] if x['edition']==20);ed.update(status='planned',artworks=[i['id'] for i in items],text_led=[i['poem_id'] for i in plain],batch=str((B/'batch.json').relative_to(R)),direction=b['direction']);q['active_batch']=dict(id='edition-20',owner='current-chat-assistant',started_at=now,status='running');q['updated_at']=now;(K/'queue.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n')
print('Edition20 planned; all11 source snapshots retained.')
